    // Provider landing page
    "provPage.hero.subtitle": "Toome sulle kliente, kes parasjagu kolivad — päringud inimestelt, kes vajavad kolimist (sh pakkimisabi), hoiuruumi, haagist, kaubikut või koristust. Liitumine on tasuta, vahendustasu 0%. Broneeringud, lepingud ja maksed on valikulised tööriistad.",
