    "hiw.step3desc": "Pakkumised jõuavad su postkasti sedamööda, kuidas partnerid vastavad. Võrdle hinda ja tingimusi rahulikult.",
    "hiw.step4": "Vali ja lepi kokku",
    "hiw.step4desc": "Suhtle valitud partneriga otse ja lepi detailid kokku. Ruumly on kliendile tasuta ega lisa hinnale midagi.",
